const E=8,b=81,H=256;function u(){const n=new Uint8Array(81);for(let t=0;t<=8;t+=1)for(let A=0;A<=8;A+=1){const c=2*(Math.min(A,t)+.5)/(A+t+1);n[A+9*t]=Math.round(c*255)}return n}function R(){return Uint8Array.from({length:256},(n,t)=>t)}function r(n){return[n>>>24&255,n>>>16&255,n>>>8&255,n&255]}function D(n){let t=4294967295;for(const A of n){t^=A;for(let c=0;c<8;c+=1)t=t>>>1^3988292384&-(t&1)}return(t^4294967295)>>>0}function h(n,t){const A=[...n].map(c=>c.charCodeAt(0)).concat(t);return[...r(t.length),...A,...r(D(A))]}function M(n){const t=[0,...n],A=t.length;let c=1,i=0;for(const e of t)c=(c+e)%65521,i=(i+c)%65521;const f=[120,1,1,A&255,A>>>8,~A&255,~A>>>8&255,...t,...r(i<<16|c)],o=[137,80,78,71,13,10,26,10,...h("IHDR",[...r(n.length),...r(1),8,0,0,0,0]),...h("IDAT",f),...h("IEND",[])],a="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let s="";for(let e=0;e<o.length;e+=3){const S=o[e],l=o[e+1]??0,g=o[e+2]??0,_=S<<16|l<<8|g;s+=a.charAt(_>>>18&63)+a.charAt(_>>>12&63),s+=e+1<o.length?a.charAt(_>>>6&63):"=",s+=e+2<o.length?a.charAt(_&63):"="}return`data:image/png;base64,${s}`}const N=M(u()),U=M(R());export{N as SMAA_AREATEX_PNG,b as SMAA_AREA_WIDTH,E as SMAA_MAX_RUN,U as SMAA_SEARCHTEX_PNG,H as SMAA_SEARCH_WIDTH,u as generateSmaaAreaData,R as generateSmaaSearchData};
